//! Porter desktop theme tokens. Generated by hand from docs/design/tokens/tokens.json.
//! Reference copy: the app's live theme is crates/porter-desktop/src/theme.rs.

use gpui::{px, rgb, Hsla, Pixels};

#[derive(Clone, Copy, Debug)]
pub struct Tokens {
    pub bg: Hsla,
    pub surface: Hsla,
    pub panel: Hsla,
    pub hover: Hsla,
    pub border: Hsla,
    pub border_strong: Hsla,
    pub text: Hsla,
    pub muted: Hsla,
    pub faint: Hsla,
    pub accent: Hsla,
    pub accent_bg: Hsla,
    pub on_accent: Hsla,
    /// Only for "clean and actually written". Never for a dry run.
    pub ok: Hsla,
    pub ok_bg: Hsla,
    pub on_ok: Hsla,
    pub warn: Hsla,
    pub warn_bg: Hsla,
    pub err: Hsla,
    pub err_bg: Hsla,
    pub err_solid: Hsla,
    pub on_err: Hsla,
    /// Interrupted (exit 3).
    pub int: Hsla,
    pub int_bg: Hsla,
    pub dry: Hsla,
    pub dry_bg: Hsla,
    pub dry_hatch: Hsla,
    pub dry_border: Hsla,
    pub stale_bg: Hsla,
}

fn c(hex: u32) -> Hsla {
    rgb(hex).into()
}

impl Tokens {
    pub fn light() -> Self {
        Self {
            bg: c(0xFFFFFF), surface: c(0xF7F7F8), panel: c(0xEFEFF2), hover: c(0xE9E9EE),
            border: c(0xE3E3E8), border_strong: c(0xCFCFD6),
            text: c(0x18181B), muted: c(0x565662), faint: c(0x6E6E7A),
            accent: c(0x3E4FD6), accent_bg: c(0xECEEFC), on_accent: c(0xFFFFFF),
            ok: c(0x17803D), ok_bg: c(0xE6F5EB), on_ok: c(0xFFFFFF),
            warn: c(0x9A5800), warn_bg: c(0xFFF3DC),
            err: c(0xC42B2B), err_bg: c(0xFDECEC), err_solid: c(0xC42B2B), on_err: c(0xFFFFFF),
            int: c(0x7339BD), int_bg: c(0xF2EBFC),
            dry: c(0x3B4A6B), dry_bg: c(0xEEF1F7), dry_hatch: c(0xE2E7F0), dry_border: c(0x8391B0),
            stale_bg: c(0xF1F1F4),
        }
    }

    pub fn dark() -> Self {
        Self {
            bg: c(0x111113), surface: c(0x17171A), panel: c(0x1E1E22), hover: c(0x26262B),
            border: c(0x2A2A30), border_strong: c(0x3A3A42),
            text: c(0xEDEDF0), muted: c(0xA3A3AE), faint: c(0x8C8C98),
            accent: c(0x8C98FF), accent_bg: c(0x1E2142), on_accent: c(0x0E1030),
            ok: c(0x4ADE80), ok_bg: c(0x0F2A19), on_ok: c(0x0B1F12),
            warn: c(0xF5B83D), warn_bg: c(0x2B210C),
            err: c(0xFF7A7A), err_bg: c(0x301515), err_solid: c(0xB42A2A), on_err: c(0x2A0F0F),
            int: c(0xC3A3FF), int_bg: c(0x231B33),
            dry: c(0xAEBBDA), dry_bg: c(0x1A1F2B), dry_hatch: c(0x222939), dry_border: c(0x56648A),
            stale_bg: c(0x1C1C20),
        }
    }
}

pub mod radius {
    use super::*;
    pub const XS: Pixels = px(4.);  // chips
    pub const SM: Pixels = px(6.);  // inputs, buttons
    pub const MD: Pixels = px(8.);  // panels, stage cards
    pub const XL: Pixels = px(14.); // sheets
}

pub mod space {
    use super::*;
    pub const S1: Pixels = px(4.);
    pub const S2: Pixels = px(8.);
    pub const S3: Pixels = px(12.);
    pub const S4: Pixels = px(16.);
    pub const S6: Pixels = px(24.);
    pub const S8: Pixels = px(32.);
}

pub mod text {
    use super::*;
    pub const TITLE: Pixels = px(20.);
    pub const HEADING: Pixels = px(15.);
    pub const BODY: Pixels = px(13.);
    pub const DENSE: Pixels = px(12.);
    pub const MICRO: Pixels = px(11.);
}

pub const ROW_TABLE: Pixels = px(28.);
pub const ROW_SIDEBAR: Pixels = px(32.);

